def transform_debug(g):
    from collections import Counter
    h, w = len(g), len(g[0])
    cnt = Counter(v for row in g for v in row)
    bg = cnt.most_common(1)[0][0]

    # Find axis columns  
    axis_cols = []
    for x in range(w):
        col_val = g[0][x]
        if col_val != bg and all(g[y][x] == col_val for y in range(h)):
            axis_cols.append(x)

    # Find axis rows
    axis_rows = []
    for y in range(h):
        if len(set(g[y])) == 1 and g[y][0] != bg:
            axis_rows.append(y)

    print(f"Background: {bg}, axis_rows: {axis_rows}, axis_cols: {axis_cols}")

    # Trace through the non-bg non-axis values
    for y in range(h):
        for x in range(w):
            v = g[y][x]
            if v != bg and v not in [3 if 4 in axis_rows else g[4][0] if 4 in axis_rows else 3 for _ in range(1)]:  # exclude axis color
                print(f"Found non-bg non-axis value {v} at ({y}, {x})")
                positions = [(y, x)]

                for ax in axis_cols:
                    mirror_x = 2 * ax - x
                    print(f"  Mirror across x={ax}: {mirror_x}")
                    if 0 <= mirror_x < w and mirror_x != x:
                        positions.append((y, mirror_x))

                for ay in axis_rows:
                    mirror_y = 2 * ay - y
                    print(f"  Mirror across y={ay}: {mirror_y}")
                    if 0 <= mirror_y < h and mirror_y != y:
                        if (mirror_y, x) not in positions:
                            positions.append((mirror_y, x))
